import { useState, useEffect, useCallback } from 'react';
import { supabase } from '@/integrations/supabase/client';

export type CmvNodeKind = 'cmv' | 'ficha' | 'insumo' | 'nf' | 'item';

export interface RawCmv {
  id: number;
  nome: string;
  ficha_tecnica_id: number;
  status: string;
  custo_calculado: number | null;
}

export interface RawCmvFicha {
  id: number;
  nome: string;
  custo_calculado: number | null;
  rendimento_quantidade: number;
  rendimento_unidade: string;
  status: string;
}

export interface RawCmvInsumo {
  id: number;
  nome: string;
  preco_custo: number | null;
  unidade_compra: string | null;
  unidade_producao: string | null;
  categoria: string | null;
  fornecedor_principal: string | null;
}

/** Produto do setor EMBALAGENS (produtos_master) */
export interface RawCmvEmbalagem {
  id: number;
  nome: string;
  preco_custo: number | null;
  unidade_medida: string | null;
}

/** Item de nota fiscal usado como custo de embalagem (achatado) */
export interface NfEmbalagemItem {
  id: number;
  nota_id: number;
  nome_produto: string | null;
  valor_unitario: number | null;
  unidade: string | null;
  fornecedor: string | null;
  numero_nota: string | null;
  data_nota: string | null;
}

/** Shape resolvido de nfItem dentro de RawCmvItem (join inlined) */
export interface ResolvedNfItem {
  id: number;
  nome_produto: string | null;
  valor_unitario: number | null;
  unidade: string | null;
  nota_id: number;
  fornecedor: string | null;
  numero_nota: string | null;
  data_nota: string | null;
}

/** Shape resolvido de produto_master dentro de RawCmvItem (join inlined) */
export interface ResolvedProdutoMaster {
  id: number;
  nome: string;
  preco_custo: number | null;
  unidade_medida: string | null;
}

export interface RawCmvItem {
  id: number;
  cmv_id: number;
  tipo: string;
  insumo_id: number | null;
  /** FK → produtos_master.id (embalagem escolhida) */
  produto_master_id: number | null;
  /** FK → itens_nota_fiscal.id (NF travada para custo) */
  nf_item_id: number | null;
  /** Fator de conversão pacote→unidade (NULL/0 = tratar como 1) */
  unidades_por_embalagem: number | null;
  quantidade: number;
  unidade: string;
  preco_unitario_esboco: number | null;
  observacao: string | null;
  custo_calculado: number | null;
  ordem: number;
  insumo?: RawCmvInsumo;
  produtoMaster?: ResolvedProdutoMaster;
  nfItem?: ResolvedNfItem;
}

export interface RawCmvNF {
  id: number;
  fornecedor: string | null;
  numero_nota: string | null;
  valor_total: number | null;
  data_nota: string | null;
}

export interface RawCmvNFItem {
  id: number;
  nota_id: number;
  insumo_id: number | null;
  nome_produto: string | null;
  valor_unitario: number | null;
  peso_unitario: number | null;
  unidade_base: string | null;
  unidade: string | null;
}

export const cmvNodeId = (id: number) => `cmv_${id}`;
export const fichaNodeId = (id: number) => `ficha_${id}`;
export const insumoNodeId = (id: number) => `insumo_${id}`;
export const nfNodeId = (id: number) => `nf_${id}`;

export const parseNodeId = (key: string): { type: CmvNodeKind; id: number } | null => {
  const idx = key.indexOf('_');
  if (idx < 0) return null;
  const typeStr = key.slice(0, idx);
  const id = Number(key.slice(idx + 1));
  if (!Number.isFinite(id)) return null;
  const validTypes: CmvNodeKind[] = ['cmv', 'ficha', 'insumo', 'nf', 'item'];
  if (validTypes.includes(typeStr as CmvNodeKind)) {
    return { type: typeStr as CmvNodeKind, id };
  }
  return null;
};

export interface CmvGraphData {
  loading: boolean;
  cmv: RawCmv | null;
  fichaData: RawCmvFicha | null;
  items: RawCmvItem[];
  insumos: RawCmvInsumo[];
  /** Catálogo de produtos do setor EMBALAGENS para o seletor de embalagem */
  embalagens: RawCmvEmbalagem[];
  /** Itens de NF filtrados por categoria='Embalagens' para atrelar custo */
  nfEmbalagemItems: NfEmbalagemItem[];
  /** Notas fiscais gerais (retrocompat) */
  notas: RawCmvNF[];
  /** Itens de NF vinculados a insumos (retrocompat) */
  nfItems: RawCmvNFItem[];
  positions: Map<string, { x: number; y: number }>;
  savePosition: (key: string, x: number, y: number) => Promise<void>;
  refetch: () => Promise<void>;
}

export function useCmvGraph(cmvId: number | null): CmvGraphData {
  const [loading, setLoading] = useState<boolean>(true);
  const [cmv, setCmv] = useState<RawCmv | null>(null);
  const [fichaData, setFichaData] = useState<RawCmvFicha | null>(null);
  const [items, setItems] = useState<RawCmvItem[]>([]);
  const [insumos, setInsumos] = useState<RawCmvInsumo[]>([]);
  const [embalagens, setEmbalagens] = useState<RawCmvEmbalagem[]>([]);
  const [nfEmbalagemItems, setNfEmbalagemItems] = useState<NfEmbalagemItem[]>([]);
  const [notas, setNotas] = useState<RawCmvNF[]>([]);
  const [nfItems, setNfItems] = useState<RawCmvNFItem[]>([]);
  const [positions, setPositions] = useState<Map<string, { x: number; y: number }>>(new Map());

  const fetchAll = useCallback(async () => {
    if (cmvId === null) {
      setLoading(false);
      return;
    }

    setLoading(true);

    try {
      const [
        cmvRes,
        itensRes,
        insumosRes,
        posRes,
        nfRes,
        nfItensRes,
        embalagensRes,
        nfEmbalagemRes,
      ] = await Promise.all([
        supabase
          .from('cmv_fichas')
          .select('*, fichas_tecnicas(*)')
          .eq('id', cmvId)
          .maybeSingle(),
        supabase
          .from('cmv_itens')
          .select(
            '*, insumos(id,nome,preco_custo,unidade_compra,unidade_producao,categoria,fornecedor_principal), produtos_master(id,nome,preco_custo,unidade_medida), itens_nota_fiscal(id,nome_produto,valor_unitario,unidade,nota_id,notas_fiscais(fornecedor,numero_nota,data_nota))',
          )
          .eq('cmv_id', cmvId)
          .order('ordem'),
        supabase
          .from('insumos')
          .select('id,nome,preco_custo,unidade_compra,unidade_producao,categoria,fornecedor_principal')
          .eq('ativo', true)
          .order('nome'),
        supabase
          .from('cmv_canvas_positions')
          .select('*')
          .eq('cmv_id', cmvId),
        supabase
          .from('notas_fiscais')
          .select('id,fornecedor,numero_nota,valor_total,data_nota')
          .order('data_nota', { ascending: false })
          .limit(80),
        supabase
          .from('itens_nota_fiscal')
          .select('id,nota_id,insumo_id,nome_produto,valor_unitario,peso_unitario,unidade_base,unidade')
          .not('insumo_id', 'is', null)
          .limit(2000),
        // Catálogo de embalagens: produtos_master com setor = 'EMBALAGENS'
        supabase
          .from('produtos_master')
          .select('id,nome,preco_custo,unidade_medida,setor')
          .eq('ativo', true)
          .eq('setor', 'EMBALAGENS')
          .order('nome'),
        // Candidatos de NF para atrelar custo de embalagem
        supabase
          .from('itens_nota_fiscal')
          .select(
            'id,nota_id,nome_produto,valor_unitario,unidade,peso_unitario,notas_fiscais(fornecedor,numero_nota,data_nota)',
          )
          .eq('categoria', 'Embalagens')
          .gt('valor_unitario', 0)
          .limit(1000),
      ]);

      // --- cmv_fichas + fichas_tecnicas ---
      if (cmvRes.data) {
        const raw = cmvRes.data as Record<string, unknown>;
        setCmv({
          id: raw.id as number,
          nome: raw.nome as string,
          ficha_tecnica_id: raw.ficha_tecnica_id as number,
          status: raw.status as string,
          custo_calculado: raw.custo_calculado as number | null,
        });

        if (raw.fichas_tecnicas) {
          const ft = raw.fichas_tecnicas;
          const ficha = Array.isArray(ft) ? ft[0] : ft;
          if (ficha) {
            const f = ficha as Record<string, unknown>;
            setFichaData({
              id: f.id as number,
              nome: f.nome as string,
              custo_calculado: f.custo_calculado as number | null,
              rendimento_quantidade: f.rendimento_quantidade as number,
              rendimento_unidade: f.rendimento_unidade as string,
              status: f.status as string,
            });
          }
        }
      } else {
        setCmv(null);
        setFichaData(null);
      }

      // --- cmv_itens com joins novos ---
      if (itensRes.data) {
        const mappedItems = (itensRes.data as Record<string, unknown>[]).map((item) => {
          // insumo (legado)
          const insumosData = item.insumos;
          const insumoObj = insumosData
            ? Array.isArray(insumosData)
              ? insumosData[0]
              : insumosData
            : undefined;

          // produto_master (embalagem escolhida)
          const pmData = item.produtos_master;
          const pmObj = pmData
            ? Array.isArray(pmData)
              ? pmData[0]
              : pmData
            : undefined;
          let produtoMaster: ResolvedProdutoMaster | undefined;
          if (pmObj) {
            const pm = pmObj as Record<string, unknown>;
            produtoMaster = {
              id: pm.id as number,
              nome: pm.nome as string,
              preco_custo: pm.preco_custo as number | null,
              unidade_medida: pm.unidade_medida as string | null,
            };
          }

          // itens_nota_fiscal (NF travada) com notas_fiscais aninhado
          const nfItemData = item.itens_nota_fiscal;
          const nfItemObj = nfItemData
            ? Array.isArray(nfItemData)
              ? nfItemData[0]
              : nfItemData
            : undefined;
          let nfItem: ResolvedNfItem | undefined;
          if (nfItemObj) {
            const nfi = nfItemObj as Record<string, unknown>;
            const nfaNested = nfi.notas_fiscais;
            const nfa = nfaNested
              ? Array.isArray(nfaNested)
                ? (nfaNested[0] as Record<string, unknown>)
                : (nfaNested as Record<string, unknown>)
              : null;
            nfItem = {
              id: nfi.id as number,
              nome_produto: nfi.nome_produto as string | null,
              valor_unitario: nfi.valor_unitario as number | null,
              unidade: nfi.unidade as string | null,
              nota_id: nfi.nota_id as number,
              fornecedor: nfa ? (nfa.fornecedor as string | null) : null,
              numero_nota: nfa ? (nfa.numero_nota as string | null) : null,
              data_nota: nfa ? (nfa.data_nota as string | null) : null,
            };
          }

          const mapped: RawCmvItem = {
            id: item.id as number,
            cmv_id: item.cmv_id as number,
            tipo: item.tipo as string,
            insumo_id: item.insumo_id as number | null,
            produto_master_id: (item.produto_master_id as number | null) ?? null,
            nf_item_id: (item.nf_item_id as number | null) ?? null,
            unidades_por_embalagem: (item.unidades_por_embalagem as number | null) ?? null,
            quantidade: item.quantidade as number,
            unidade: item.unidade as string,
            preco_unitario_esboco: item.preco_unitario_esboco as number | null,
            observacao: item.observacao as string | null,
            custo_calculado: item.custo_calculado as number | null,
            ordem: item.ordem as number,
            insumo: insumoObj as RawCmvInsumo | undefined,
            produtoMaster,
            nfItem,
          };
          return mapped;
        });
        setItems(mappedItems);
      } else {
        setItems([]);
      }

      // --- insumos ativos (catálogo retrocompat) ---
      if (insumosRes.data) {
        setInsumos(insumosRes.data as unknown as RawCmvInsumo[]);
      }

      // --- canvas positions ---
      if (posRes.data) {
        const newPositions = new Map<string, { x: number; y: number }>();
        for (const pos of posRes.data as Record<string, unknown>[]) {
          const key = `${pos.node_type}_${pos.node_id}`;
          newPositions.set(key, { x: pos.x as number, y: pos.y as number });
        }
        setPositions(newPositions);
      } else {
        setPositions(new Map());
      }

      // --- notas fiscais (retrocompat) ---
      if (nfRes.data) {
        setNotas(nfRes.data as unknown as RawCmvNF[]);
      }

      // --- itens NF por insumo (retrocompat) ---
      if (nfItensRes.data) {
        setNfItems(nfItensRes.data as unknown as RawCmvNFItem[]);
      }

      // --- catálogo de embalagens ---
      if (embalagensRes.data) {
        const mapped = (embalagensRes.data as Record<string, unknown>[]).map((p) => ({
          id: p.id as number,
          nome: p.nome as string,
          preco_custo: p.preco_custo as number | null,
          unidade_medida: p.unidade_medida as string | null,
        }));
        setEmbalagens(mapped);
      } else {
        setEmbalagens([]);
      }

      // --- itens de NF de embalagem (candidatos para atrelar custo) ---
      if (nfEmbalagemRes.data) {
        // Ordenar client-side por data_nota desc (embed aninhado impede order no PostgREST)
        const mapped = (nfEmbalagemRes.data as Record<string, unknown>[])
          .map((row) => {
            const nfaNested = row.notas_fiscais;
            const nfa = nfaNested
              ? Array.isArray(nfaNested)
                ? (nfaNested[0] as Record<string, unknown>)
                : (nfaNested as Record<string, unknown>)
              : null;
            const item: NfEmbalagemItem = {
              id: row.id as number,
              nota_id: row.nota_id as number,
              nome_produto: row.nome_produto as string | null,
              valor_unitario: row.valor_unitario as number | null,
              unidade: row.unidade as string | null,
              fornecedor: nfa ? (nfa.fornecedor as string | null) : null,
              numero_nota: nfa ? (nfa.numero_nota as string | null) : null,
              data_nota: nfa ? (nfa.data_nota as string | null) : null,
            };
            return item;
          })
          .sort((a, b) => {
            // desc por data_nota (string ISO)
            if (!a.data_nota && !b.data_nota) return 0;
            if (!a.data_nota) return 1;
            if (!b.data_nota) return -1;
            return b.data_nota.localeCompare(a.data_nota);
          });
        setNfEmbalagemItems(mapped);
      } else {
        setNfEmbalagemItems([]);
      }
    } catch (err) {
      console.error('[useCmvGraph] fetchAll error:', err);
    } finally {
      setLoading(false);
    }
  }, [cmvId]);

  useEffect(() => {
    fetchAll();
  }, [fetchAll]);

  const savePosition = useCallback(
    async (key: string, x: number, y: number) => {
      if (cmvId === null) return;

      const parsed = parseNodeId(key);
      if (!parsed) return;

      // Update local state optimistically
      setPositions((prev) => {
        const next = new Map(prev);
        next.set(key, { x, y });
        return next;
      });

      try {
        const { error } = await supabase
          .from('cmv_canvas_positions')
          .upsert(
            {
              cmv_id: cmvId,
              node_type: parsed.type,
              node_id: parsed.id,
              x,
              y,
            },
            { onConflict: 'cmv_id,node_type,node_id' },
          );

        if (error) {
          console.error('[useCmvGraph] savePosition error:', error);
        }
      } catch (err) {
        console.error('[useCmvGraph] savePosition exception:', err);
      }
    },
    [cmvId],
  );

  return {
    loading,
    cmv,
    fichaData,
    items,
    insumos,
    embalagens,
    nfEmbalagemItems,
    notas,
    nfItems,
    positions,
    savePosition,
    refetch: fetchAll,
  };
}

